#include "Buildings/FoundrylineRoofLayout.h"
namespace {
TArray<FBox2D> Subtract(const TArray<FBox2D>& Input,const FBox2D& Cut){TArray<FBox2D> Out;for(const auto& A:Input){const auto Low=A.Min.ComponentMax(Cut.Min),High=A.Max.ComponentMin(Cut.Max);if(Low.X>=High.X||Low.Y>=High.Y){Out.Add(A);continue;}auto Add=[&](FVector2D L,FVector2D H){if(H.X-L.X>.01&&H.Y-L.Y>.01)Out.Add({L,H});};Add(A.Min,{Low.X,A.Max.Y});Add({High.X,A.Min.Y},A.Max);Add({Low.X,A.Min.Y},{High.X,Low.Y});Add({Low.X,High.Y},{High.X,A.Max.Y});}return Out;}
int Count(double Length,double Foot,double Margin,double Spacing){const int Max=FMath::FloorToInt32(Length/(Foot+2*Margin));return Max<1?0:FMath::Clamp(FMath::RoundToInt32(Length/Spacing),1,FMath::Min(8,Max));}
}
TArray<FBox2D> FFoundrylineRoofLayout::OfficeZones(const FFoundrylinePlacedObject& O,float W,float D){TArray<FBox2D> Open={FBox2D({0,0},{W,D})},Out;for(const auto& Room:O.OfficeRooms){const FBox2D R(FVector2D(Room.Min),FVector2D(Room.Max));Out.Add(R);Open=Subtract(Open,R);}Out.Append(Open);return Out;}
TArray<FFoundrylineRoofLayout::FWindow> FFoundrylineRoofLayout::Windows(const FFoundrylinePlacedObject& O,float W,float D){
 TArray<FWindow> Out;const auto Zones=O.bOfficeAnnex?OfficeZones(O,W,D):TArray<FBox2D>{FBox2D({0,0},{W,D})};for(const auto& Zone:Zones){const auto S=Zone.GetSize();const FVector2D Size=O.bOfficeAnnex?(S.X>=S.Y?FVector2D(121.92,91.44):FVector2D(91.44,121.92)):FVector2D(400,400);const double Margin=O.bOfficeAnnex?60:100,Spacing=O.bOfficeAnnex?600:1000;const int NX=Count(S.X,Size.X,Margin,Spacing),NY=Count(S.Y,Size.Y,Margin,Spacing);for(int X=0;X<NX;++X)for(int Y=0;Y<NY;++Y)Out.Add({Zone.Min+FVector2D((X+.5)*S.X/NX,(Y+.5)*S.Y/NY),Size,O.bOfficeAnnex});}return Out;
}
TArray<FBox2D> FFoundrylineRoofLayout::SolidPanels(float W,float D,const TArray<FWindow>& Windows){TArray<FBox2D> Out={FBox2D({0,0},{W,D})};for(const auto& Window:Windows)Out=Subtract(Out,Window.Bounds());return Out;}
TArray<FFoundrylineRoofLayout::FFixture> FFoundrylineRoofLayout::OfficeFixtures(const FFoundrylinePlacedObject& O,float W,float D){
 TArray<FFixture> Out;const auto Skylights=Windows(O,W,D);for(const auto& Zone:OfficeZones(O,W,D)){const auto S=Zone.GetSize();const FVector2D Size=S.X>=S.Y?FVector2D(121.92,60.96):FVector2D(60.96,121.92);const int NX=FMath::Clamp(FMath::RoundToInt32(S.X/300),1,12),NY=FMath::Clamp(FMath::RoundToInt32(S.Y/300),1,12);for(int X=0;X<NX;++X)for(int Y=0;Y<NY;++Y){const auto Desired=Zone.Min+FVector2D((X+.5)*S.X/NX,(Y+.5)*S.Y/NY);TArray<FVector2D> Candidates={Desired};for(float Radius:{45.f,90.f,135.f,180.f,240.f}){Candidates.Add(Desired+FVector2D(Radius,0));Candidates.Add(Desired-FVector2D(Radius,0));Candidates.Add(Desired+FVector2D(0,((X+Y)%2?1:-1)*Radius));Candidates.Add(Desired-FVector2D(0,((X+Y)%2?1:-1)*Radius));}for(const auto C:Candidates){const FBox2D Bounds(C-Size/2,C+Size/2);if(Bounds.Min.X<Zone.Min.X+25||Bounds.Min.Y<Zone.Min.Y+25||Bounds.Max.X>Zone.Max.X-25||Bounds.Max.Y>Zone.Max.Y-25)continue;if(Skylights.ContainsByPredicate([&](const auto& V){return V.Bounds().ExpandBy(18).Intersect(Bounds.ExpandBy(8));}))continue;if(Out.ContainsByPredicate([&](const auto& V){return FBox2D(V.Center-V.Size/2,V.Center+V.Size/2).ExpandBy(12).Intersect(Bounds);}))continue;Out.Add({C,Size});break;}}}return Out;
}
